#import <Foundation/Foundation.h>
#import <AppKit/AppKit.h>
#include "_cgo_export.h" // Generated by CGO, defines goSleepCallback

@interface SleepObserver : NSObject
@end

@implementation SleepObserver
- (void)receiveSleepNote:(NSNotification *)note {
    goSleepCallback(1);
}
- (void)receiveWakeNote:(NSNotification *)note {
    goSleepCallback(0);
}
@end

static SleepObserver *observer;

void startSleepObserver() {
    if (observer) return;
    observer = [[SleepObserver alloc] init];
    [[[NSWorkspace sharedWorkspace] notificationCenter] addObserver:observer
           selector:@selector(receiveSleepNote:)
           name:NSWorkspaceWillSleepNotification
           object:nil];
    [[[NSWorkspace sharedWorkspace] notificationCenter] addObserver:observer
           selector:@selector(receiveWakeNote:)
           name:NSWorkspaceDidWakeNotification
           object:nil];
}

void stopSleepObserver() {
    if (observer) {
        [[[NSWorkspace sharedWorkspace] notificationCenter] removeObserver:observer];
        observer = nil;
    }
}
